cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fused scaled-dot-product-attention kernel (flash-attention style, online softmax)
// One block handles BLOCK_M query rows for a single (batch, head) pair.
// One warp handles one query row; lanes within the warp split the head-dim.
__global__ void fused_attn_kernel(
    const half_t* __restrict__ Qg,
    const half_t* __restrict__ Kg,
    const half_t* __restrict__ Vg,
    half_t* __restrict__ Og,
    int B, int H, int N, int D,
    float scale)
{
  extern __shared__ half_t smem[];
  half_t* sK = smem;
  half_t* sV = smem + D;

  const int bh = blockIdx.y;      // 0 .. B*H-1
  const int b  = bh / H;
  const int h  = bh % H;
  const int64_t base = ((int64_t)b * H + h) * (int64_t)N * (int64_t)D;

  // Global tensor views for this (b,h) slice, shaped (N, D)
  auto mQ = make_tensor(make_gmem_ptr(Qg + base), make_shape(N, D), make_stride(D, 1));
  auto mK = make_tensor(make_gmem_ptr(Kg + base), make_shape(N, D), make_stride(D, 1));
  auto mV = make_tensor(make_gmem_ptr(Vg + base), make_shape(N, D), make_stride(D, 1));
  auto mO = make_tensor(make_gmem_ptr(Og + base), make_shape(N, D), make_stride(D, 1));

  const int tid  = threadIdx.x;
  const int warp = tid / 32;
  const int lane = tid % 32;
  const int BLOCK_M = blockDim.x / 32;

  const int i = blockIdx.x * BLOCK_M + warp;  // query row handled by this warp

  const int chunk = D / 32;      // number of head-dim elements handled by this lane
  constexpr int MAXC = 32;       // supports D up to 32*32 = 1024 (fits this workload)

  float q_reg[MAXC];
  float acc[MAXC];

  const bool active = (i < N);

  if (active) {
    #pragma unroll
    for (int t = 0; t < MAXC; ++t) {
      if (t < chunk) {
        int d = lane * chunk + t;
        q_reg[t] = float(mQ(i, d));
        acc[t] = 0.0f;
      }
    }
  }

  float m = -INFINITY;
  float l = 0.0f;

  for (int j = 0; j < N; ++j) {
    // Cooperatively load K_j and V_j into shared memory (coalesced)
    for (int d = tid; d < D; d += blockDim.x) {
      sK[d] = mK(j, d);
      sV[d] = mV(j, d);
    }
    __syncthreads();

    if (active) {
      float partial = 0.0f;
      #pragma unroll
      for (int t = 0; t < MAXC; ++t) {
        if (t < chunk) {
          int d = lane * chunk + t;
          partial += q_reg[t] * float(sK[d]);
        }
      }
      // warp reduction over the 32 lanes
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) {
        partial += __shfl_down_sync(0xffffffffu, partial, off);
      }
      partial = __shfl_sync(0xffffffffu, partial, 0);

      float score = partial * scale;

      float new_m = fmaxf(m, score);
      float correction = expf(m - new_m);
      float p = expf(score - new_m);
      l = l * correction + p;

      #pragma unroll
      for (int t = 0; t < MAXC; ++t) {
        if (t < chunk) {
          int d = lane * chunk + t;
          acc[t] = acc[t] * correction + p * float(sV[d]);
        }
      }
      m = new_m;
    }
    __syncthreads();
  }

  if (active) {
    #pragma unroll
    for (int t = 0; t < MAXC; ++t) {
      if (t < chunk) {
        int d = lane * chunk + t;
        mO(i, d) = half_t(acc[t] / l);
      }
    }
  }
}

torch::Tensor fused_sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q,K,V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be 4D [B,H,N,D]");

  auto Qc = Q.contiguous();
  auto Kc = K.contiguous();
  auto Vc = V.contiguous();

  int64_t B = Qc.size(0);
  int64_t H = Qc.size(1);
  int64_t N = Qc.size(2);
  int64_t D = Qc.size(3);

  TORCH_CHECK(Kc.size(0) == B && Kc.size(1) == H && Kc.size(2) == N && Kc.size(3) == D,
              "K shape must match Q");
  TORCH_CHECK(Vc.size(0) == B && Vc.size(1) == H && Vc.size(2) == N && Vc.size(3) == D,
              "V shape must match Q");

  constexpr int BLOCK_M = 4;
  TORCH_CHECK(N % BLOCK_M == 0, "sequence length must be divisible by 32 for this kernel");
  TORCH_CHECK(D % 32 == 0 && D <= 1024, "head dim must be divisible by 32 and <= 1024");

  auto O = torch::empty_like(Qc);

  dim3 grid((unsigned)(N / BLOCK_M), (unsigned)(B * H));
  dim3 block((unsigned)(BLOCK_M * 32));
  size_t smem_bytes = 2 * (size_t)D * sizeof(half_t);

  float scale = 1.0f / sqrtf((float)D);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  fused_attn_kernel<<<grid, block, smem_bytes, stream>>>(
      reinterpret_cast<const half_t*>(Qc.data_ptr<at::Half>()),
      reinterpret_cast<const half_t*>(Kc.data_ptr<at::Half>()),
      reinterpret_cast<const half_t*>(Vc.data_ptr<at::Half>()),
      reinterpret_cast<half_t*>(O.data_ptr<at::Half>()),
      (int)B, (int)H, (int)N, (int)D, scale);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "fused_attn_kernel launch failed: ", cudaGetErrorString(err));

  return O;
}
"""

